widgetType\":\"text-editor\"}],\"isInner\":false}],\"isInner\":false},{\"id\":\"section4\",\"elType\":\"section\",\"settings\":{\"_element_id\":\"content-research\"},\"elements\":[{\"id\":\"column4\",\"elType\":\"column\",\"settings\":{\"_column_size\":100},\"elements\":[],\"isInner\":false}],\"isInner\":false},{\"id\":\"section5\",\"elType\":\"section\",\"settings\":{\"_element_id\":\"content-trust\"},\"elements\":[{\"id\":\"column5\",\"elType\":\"column\",\"settings\":{\"_column_size\":100},\"elements\":[],\"isInner\":false}],\"isInner\":false},{\"id\":\"section6\",\"elType\":\"section\",\"settings\":{\"_element_id\":\"cta-section\"},\"elements\":[{\"id\":\"column6\",\"elType\":\"column\",\"settings\":{\"_column_size\":100},\"elements\":[],\"isInner\":false}],\"isInner\":false}]'),(28608,1256,'_wp_page_template','default'),(28609,1256,'_elementor_version','3.28.2'),(28610,1256,'_elementor_pro_version','3.20.2'),(28614,1257,'_elementor_edit_mode','builder'),(28615,1257,'_elementor_template_type','wp-page'),(28616,1257,'_elementor_data','[{\"id\":\"section1\",\"elType\":\"section\",\"settings\":{\"_element_id\":\"hero-section\",\"background_background\":\"gradient\",\"background_gradient_angle\":{\"unit\":\"deg\",\"size\":135},\"background_gradient_color\":\"#0a3d62\",\"background_gradient_color_stop\":{\"unit\":\"%\",\"size\":0},\"background_gradient_color_b\":\"#1e3799\",\"background_gradient_color_b_stop\":{\"unit\":\"%\",\"size\":100},\"padding\":{\"unit\":\"px\",\"top\":\"100\",\"right\":\"30\",\"bottom\":\"100\",\"left\":\"30\",\"isLinked\":false},\"background_color\":\"#0A3D62\",\"background_color_b\":\"#1E3799\"},\"elements\":[{\"id\":\"column1\",\"elType\":\"column\",\"settings\":{\"_column_size\":100},\"elements\":[{\"id\":\"7cfaf6f\",\"elType\":\"widget\",\"settings\":{\"title\":\"Where Complex Therapies Meet Compassionate Home Care\",\"header_size\":\"h1\",\"align\":\"center\",\"typography_typography\":\"custom\",\"typography_font_size\":{\"unit\":\"px\"