INSERT INTO `lqbk_snippets` VALUES (5,'Email Check','','/**\n * Check email address exists.\n *\n * @link    https://wpforms.com/developers/wpforms_user_registration_process_registration_process_user_email_exists_error_message/\n *\n * @param   string   $msg  Message that displays if email exists.\n * @return  string\n */\n \nfunction wpf_dev_user_registration_email_exists( $msg ) {\n  \n    // This is the message that would appear\n    $msg =  __(\'A user with that email already exists. Please <a href=\"https://mobilemedicalla.com/rns-portal/\">log in here</a> to your account.\', \'text-domain\');\n  \n    return $msg;\n}\n  \nadd_filter( \'wpforms_user_registration_process_registration_process_user_email_exists_error_message\', \'wpf_dev_user_registration_email_exists\', 10, 1 );\n','','global',10,1,'2024-03-30 22:06:40',4,NULL),(6,'Failed Attempts','','// Hook into the login failure event\nadd_action( \'wp_login_failed\', \'update_failed_login_attempt\', 10, 1 );\n\nfunction update_failed_login_attempt( $username ) {\n    // Retrieve user data based on the username\n    $user = get_user_by( \'login\', $username );\n\n    if ( $user ) {\n        // Get the user ID\n        $user_id = $user->ID;\n\n        // Get the current number of failed attempts\n        $failed_attempts = (int) get_user_meta( $user_id, \'failedattempts\', true );\n\n        // Increment the number of failed attempts\n        $failed_attempts++;\n\n        // Update the failed attempts count in the database\n        update_user_meta( $user_id, \'failedattempts\', $failed_attempts );\n    }\n}\n','','global',10,1,'2024-04-06 17:31:21',3,NULL),(7,'Reset Password','','add_filter( \'lostpassword_url\', \'my_lostpassword_url\' );\nfunction my_lostpassword_url() {\nreturn home_url(\'/password-reset/\');\n}','','global',10,1,'2024-04-06 21:05:33',3,NULL),(8,'Email Validation','','add_filter( \'wpforms_process_validate_email\', \'custom_wpforms_validate_email\', 10, 3 );\nfunction custom_wpforms_validate_email( $field_id, $field_submit, $form_data ) {\n    if ( empty( $field_submit ) || ! is_email( $field_submit ) ) {\n        wpforms()->process->errors[ $form_data[\'id\'] ][ $field_id ] = \'The email address you entered cannot be accepted. Please enter another email address.\';\n    }\n}\n','','global',10,1,'2024-04-13 19:27:57',3,NULL);
/*!40000 ALTER TABLE `lqbk_snippets` ENABLE KEYS */;
UNLOCK TABLES;

